import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.CdvW4CUT.js";const m=JSON.parse('{"title":"Setting up a display","description":"","frontmatter":{},"headers":[],"relativePath":"guide/displays.md","filePath":"guide/displays.md","lastUpdated":1793095158000}'),n={name:"guide/displays.md"};function i(r,e,h,l,d,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="setting-up-a-display" tabindex="-1">Setting up a display <a class="header-anchor" href="#setting-up-a-display" aria-label="Permalink to &quot;Setting up a display&quot;">​</a></h1><p>Any tablet with a modern-ish browser will do, down to old Fire tablets on Fire OS 5. Open your Frog Hub site on it, full screen: in <a href="https://www.fully-kiosk.com" target="_blank" rel="noreferrer">Fully Kiosk Browser</a>, or in <a href="/developers/android">Frog Hub&#39;s own Android app</a>, which keeps the screen on, plays sound without a tap and copes with Fire OS 5&#39;s certificate problems.</p><h2 id="getting-the-app" tabindex="-1">Getting the app <a class="header-anchor" href="#getting-the-app" aria-label="Permalink to &quot;Getting the app&quot;">​</a></h2><p><a class="download" href="https://github.com/froghub-assistant/froghub/releases/latest/download/froghub.apk">⬇️ Download the display app (froghub.apk)</a></p><p>On the tablet, open that link (or copy the file over), then allow installing from unknown sources when it asks: on a Fire tablet that&#39;s <strong>Settings → Security &amp; Privacy → Apps from Unknown Sources</strong>. It asks for your Frog Hub&#39;s address on first start. There&#39;s an <a href="/developers/android#the-admin-app">admin app for phones</a> too.</p><h2 id="the-welcome" tabindex="-1">The welcome <a class="header-anchor" href="#the-welcome" aria-label="Permalink to &quot;The welcome&quot;">​</a></h2><p>A display with no Home Assistant token opens the welcome: hello, connect, pick a personality, who it&#39;s for and which room, a microphone check, then confetti.</p><p>There are three ways to connect it:</p><ul><li><strong>📱 Scan with a phone.</strong> The display shows a QR code. A grown-up scans it, types the PIN on their phone and taps <em>Pair it</em>; the display copies the connection and settings from the other Frog Hubs.</li><li><strong>🏠 Log in with Home Assistant.</strong> It goes to Home Assistant&#39;s login page and comes back with a long-lived token made just for that display. Nothing to set up in Home Assistant.</li><li><strong>The PIN, or a token.</strong> A grown-up&#39;s PIN on the display copies the connection and settings from the other Frog Hubs, or type Home Assistant&#39;s address and a token yourself.</li></ul><div class="tip custom-block"><p class="custom-block-title">Trying the welcome again</p><p>Admin Settings has &quot;✨ Show the welcome again&quot;. <code>?welcome</code> on the address (or <code>?welcome=mic</code>, a step&#39;s name) opens it on any display to try it out.</p></div><h2 id="without-home-assistant" tabindex="-1">Without Home Assistant <a class="header-anchor" href="#without-home-assistant" aria-label="Permalink to &quot;Without Home Assistant&quot;">​</a></h2><p>Home Assistant is optional (&quot;Skip: use it without Home Assistant&quot;). Without it there&#39;s no voice (wake word, speech and replies all go through Home Assistant), no room buttons and no weather; typed questions are answered on screen, and alarms, 📢 messages and cards still work. Adding Home Assistant&#39;s address and a token in Settings later turns the voice on.</p><h2 id="its-name-and-room" tabindex="-1">Its name and room <a class="header-anchor" href="#its-name-and-room" aria-label="Permalink to &quot;Its name and room&quot;">​</a></h2><p>Each display has a random id and a name (Settings → &quot;This display&#39;s name&quot;, by default its room&#39;s name). The name is how you send it messages or announcements, and the room decides which devices it can control.</p><h2 id="grown-ups-displays" tabindex="-1">Grown-ups&#39; displays <a class="header-anchor" href="#grown-ups-displays" aria-label="Permalink to &quot;Grown-ups&#39; displays&quot;">​</a></h2><p>Admin Settings → 🧑 Grown-ups display marks just that display (kept on the server by its id), so the assistant drops the children&#39;s rules there.</p><h2 id="mic-and-volume" tabindex="-1">Mic and volume <a class="header-anchor" href="#mic-and-volume" aria-label="Permalink to &quot;Mic and volume&quot;">​</a></h2><p>Each display has a 🎙️ button that switches its microphone off: the browser&#39;s microphone is closed, so nothing is heard or sent. Typed questions, announcements and alarms still work. The 🔊 slider sets its volume (alarms never go below 20%). Both can be changed from the admin page too.</p>',18)])])}const u=t(n,[["render",i]]);export{m as __pageData,u as default};
